/**
 * What the UI draws for one deck, read in one go.
 */
public struct DeckState: Equatable, Hashable {
    public var deck: String
    public var loaded: Bool
    public var playing: Bool
    public var composing: Bool
    public var genre: String?
    public var seed: Int64?
    /**
     * None: an endless loop.
     */
    public var structure: String?
    /**
     * "Solar Colimit".
     */
    public var title: String?
    public var tempo: Double
    public var baseTempo: Double
    /**
     * -1..1 of `pitch_range`.
     */
    public var pitch: Double
    public var pitchRange: Double
    public var volume: Double
    public var tick: Int64
    /**
     * `tick` plus the fraction of it played (the mirror's tick phase, per audio block): the
     * playhead the UI draws and extrapolates between polls.
     */
    public var position: Double
    public var totalTicks: Int64
    public var bar: Int64
    public var totalBars: Int64
    public var section: String?
    public var sections: [Section]
    /**
     * The deck's peak, 0..1.
     */
