     * "play", "pause", "stop" (None until read).
     */
    public var state: String?
    /**
     * What it plays, in words ("djrust (the phone)" while it plays our stream).
     */
    public var now: String
    /**
     * Its group, if any.
     */
    public var gid: Int64?
    /**
     * The group's leader is this zone.
     */
    public var leader: Bool
    /**
     * Playing the phone's mix (it was sent our stream and has not been stopped).
     */
    public var streaming: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(pid: Int64, name: String, model: String, ip: String, 
        /**
         * 0..100 (None until read).
         */volume: UInt8?, mute: Bool?, 
        /**
         * "play", "pause", "stop" (None until read).
         */state: String?, 
        /**
         * What it plays, in words ("djrust (the phone)" while it plays our stream).
         */now: String, 
        /**
         * Its group, if any.
         */gid: Int64?, 
        /**
         * The group's leader is this zone.
         */leader: Bool, 
        /**
         * Playing the phone's mix (it was sent our stream and has not been stopped).
         */streaming: Bool) {
        self.pid = pid
        self.name = name
        self.model = model
        self.ip = ip
