/**
 * The vocoder as the phone plays it: the internal synth (three oscillators a voice) is the
 * carrier, a deck the modulator (its rhythm and timbre shape the synth: "talking drums").
 */
public struct VocoderState: Equatable, Hashable {
    public var on: Bool
    /**
     * What shapes the synth: "A", "B" or [`WHEEL_MODULATOR`] (None: off).
     */
    public var modulator: String?
    /**
     * The notes the synth holds.
     */
    public var notes: Data
    /**
     * Levels 0..1: what comes in from the modulator, the carrier, and out.
     */
    public var modulatorLevel: Float
    public var carrierLevel: Float
    public var outLevel: Float
    /**
     * The knobs the phone shows, in their own units (see [`Player::vocoder_set`]).
     */
    public var knobs: [VocoderKnob]
    /**
     * The sound last loaded ([`Player::vocoder_preset`]), and whether a knob moved since.
     */
    public var preset: String?
    public var edited: Bool
    /**
     * Auto level: the vocoder's level kept with the decks' (the Level knob sets it around
     * that), and what it does now, dB.
     */
    public var autoLevel: Bool
    public var autoGainDb: Double

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(on: Bool, 
        /**
         * What shapes the synth: "A", "B" or [`WHEEL_MODULATOR`] (None: off).
         */modulator: String?, 
        /**
         * The notes the synth holds.
         */notes: Data, 
        /**
         * Levels 0..1: what comes in from the modulator, the carrier, and out.
         */modulatorLevel: Float, carrierLevel: Float, outLevel: Float, 
        /**
         * The knobs the phone shows, in their own units (see [`Player::vocoder_set`]).
         */knobs: [VocoderKnob], 
        /**
         * The sound last loaded ([`Player::vocoder_preset`]), and whether a knob moved since.
         */preset: String?, edited: Bool, 
        /**
         * Auto level: the vocoder's level kept with the decks' (the Level knob sets it around
         * that), and what it does now, dB.
         */autoLevel: Bool, autoGainDb: Double) {
        self.on = on
        self.modulator = modulator
        self.notes = notes
        self.modulatorLevel = modulatorLevel
        self.carrierLevel = carrierLevel
        self.outLevel = outLevel
        self.knobs = knobs
        self.preset = preset
        self.edited = edited
        self.autoLevel = autoLevel
        self.autoGainDb = autoGainDb
    }

    

    
}

