 * How long to engage: the choices under the pads.
 */

public enum FxMode: Equatable, Hashable {
    
    /**
     * Held (a transition: its own length).
     */
    case momentary
    /**
     * This many whole bars (1 to 4).
     */
    case bars(bars: UInt8
    )
    /**
     * Until let go.
     */
    case latch





}

